JWT_EXPIRATION=3600
MONGODB_URI=mongodb://localhost:27017/yourdbname
```

#### 4. Define User Model

Create a user model to interact with MongoDB. This model should include fields for email and password.

**models/User.js**:

```javascript
const mongoose = require('mongoose');

const userSchema = new mongoose.Schema({
  email: { type: String, required: true, unique: true },
  password: { type: String, required: true },
});

module.exports = mongoose.model('User', userSchema);
```

#### 5. Create Authentication Routes

Create routes for user registration and login, generating a JWT upon successful authentication.

**routes/auth.js**:

```javascript
const express = require('express');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const User = require('../models/User');
const router = express.Router();

// Register Route
router.post('/register', async (req, res) => {
    const { email, password } = req.body;
    const hashedPassword = await bcrypt.hash(password, 10);

    const user = new User({ email, password: hashedPassword });
    await user.save();
    res.status(201).send('User registered');
});

// Login Route
router.post('/login', async (req, res) => {
    const { email, password } = req.body;
    const user = await User.findOne({ email });

    if (!user || !(await bcrypt.compare(password, user.password))) {
        return res.status(401).send('Invalid credentials');
    }

    const token = jwt.sign({ id: user._id, email: user.email }, process.env.JWT_SECRET, {
        expiresIn: process.env.JWT_EXPIRATION,
    });

    res.json({ token });
});

module.exports = router;
```

#### 6. Set Up Server and Middleware

Create a basic Express server and integrate the authentication routes.

