```

#### 4.2 Event Producer

The event producer is responsible for publishing events to the Kafka topic.

```java
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;

import java.util.Properties;

public class UserEventProducer {
    private KafkaProducer<String, String> producer;

    public UserEventProducer() {
        Properties props = new Properties();
        props.put("bootstrap.servers", "localhost:9092");
        props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");

        producer = new KafkaProducer<>(props);
    }

    public void sendEvent(String eventType, String userId, String email, String name) {
        String event = String.format("{\"eventType\":\"%s\",\"userId\":\"%s\",\"timestamp\":\"%s\",\"payload\":{\"email\":\"%s\",\"name\":\"%s\"}}",
                eventType, userId, Instant.now().toString(), email, name);
        producer.send(new ProducerRecord<>("user-events", userId, event));
    }

    public void close() {
        producer.close();
    }
}
```

#### 4.3 Event Store

We need an event store to persist the events. Below is an example using Cassandra.

```java
import com.datastax.driver.core.Cluster;
import com.datastax.driver.core.Session;

public class EventStore {
    private Session session;

    public EventStore() {
        Cluster cluster = Cluster.builder().addContactPoint("127.0.0.1").build();
        session = cluster.connect("events_keyspace");
    }

    public void saveEvent(String userId, String event) {
        String query = "INSERT INTO user_events (user_id, event) VALUES (?, ?)";
        session.execute(query, userId, event);
    }
}
```

### 5. Event Processor

The event processor consumes events from the Kafka topic and updates the read model.

```java
import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.clients.consumer.ConsumerRecords;
import org.apache.kafka.clients.consumer.ConsumerRecord;

import java.time.Duration;
import java.util.Collections;
import java.util.Properties;

public class UserEventProcessor {
    private KafkaConsumer<String, String> consumer;
    private EventStore eventStore;

    public UserEventProcessor(EventStore eventStore) {
        this.eventStore = eventStore;

        Properties props = new Properties();
        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        props.put(ConsumerConfig.GROUP_ID_CONFIG, "user-event-consumer");
        props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, "org.apache.kafka.common.serialization.StringDeserializer");
        props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, "org.apache.kafka.common.serialization.StringDeserializer");

        consumer = new KafkaConsumer<>(props);
        consumer.subscribe(Collections.singletonList("user-events"));
    }

    public void processEvents() {
        while (true) {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
            for (ConsumerRecord<String, String> record : records) {
                eventStore.saveEvent(record.key(), record.value());
            }
        }
    }
}
```

