#### 4.1 Pricing Engine

**Pricing Service (Node.js):**

```javascript
const express = require('express');
const redis = require('redis');
const kafka = require('kafka-node');
const { MongoClient } = require('mongodb');

const app = express();
const redisClient = redis.createClient();
const kafkaClient = new kafka.KafkaClient({ kafkaHost: 'localhost:9092' });
const producer = new kafka.Producer(kafkaClient);

const mongoUrl = 'mongodb://localhost:27017';
const dbName = 'ecommerce';
let db;

MongoClient.connect(mongoUrl, { useNewUrlParser: true, useUnifiedTopology: true })
  .then(client => {
    db = client.db(dbName);
  })
  .catch(err => console.error(err));

app.use(express.json());

// Endpoint to get dynamic price
app.get('/price/:productId', async (req, res) => {
  const { productId } = req.params;

  // Check cache first
  redisClient.get(`price:${productId}`, async (err, price) => {
    if (price) {
      return res.json({ price: parseFloat(price), source: 'cache' });
    }

    // If not in cache, fetch from MongoDB
    const product = await db.collection('products').findOne({ _id: productId });

    // Calculate dynamic price based on demand and competitor data
    const dynamicPrice = calculateDynamicPrice(product);

    // Cache the price
    redisClient.set(`price:${productId}`, dynamicPrice, 'EX', 600); // Cache for 10 minutes

    // Publish event to Kafka
    producer.send([{ topic: 'price_updates', messages: JSON.stringify({ productId, price: dynamicPrice }) }], (error, result) => {
      if (error) {
        console.error('Error sending message to Kafka', error);
      }
    });

    return res.json({ price: dynamicPrice, source: 'db' });
  });
});

// Function to calculate dynamic price
function calculateDynamicPrice(product) {
  // Example calculation
  let basePrice = product.basePrice;
  let demandFactor = product.currentDemand / product.maxDemand; // Normalized demand
  let competitorPrice = getCompetitorPrice(product.id); // Assume this is fetched from an external service

  return Math.max(basePrice * (1 + demandFactor), competitorPrice);
}

// Function to get competitor price (mocked for simplicity)
function getCompetitorPrice(productId) {
  return Math.random() * 10 + 20; // Random price between $20 and $30
}

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Pricing service running on port ${PORT}`);
});
```

