    def process_payment(self, amount: float):
        print(f"Processing credit card payment of ${amount}")
        # Payment processing logic...

# PayPalPayment implementation
class PayPalPayment(Payment):
    def process_payment(self, amount: float):
        print(f"Processing PayPal payment of ${amount}")
        # Payment processing logic...

# Factory function
def payment_factory(payment_type: str) -> Payment:
    if payment_type == "CREDIT_CARD":
        return CreditCardPayment()
    elif payment_type == "PAYPAL":
        return PayPalPayment()
    else:
        raise ValueError(f"Unknown payment type: {payment_type}")

app = FastAPI()

@app.post("/make_payment/")
def make_payment(payment_type: str, amount: float):
    payment = payment_factory(payment_type)
    payment.process_payment(amount)
    return {"message": "Payment processed successfully."}
```

### Go

```go
package main

import (
    "fmt"
    "net/http"
    "encoding/json"
)

// Payment interface
type Payment interface {
    ProcessPayment(amount float64)
}

// CreditCardPayment implementation
type CreditCardPayment struct{}

func (cc *CreditCardPayment) ProcessPayment(amount float64) {
    fmt.Printf("Processing credit card payment of $%.2f\n", amount)
    // Payment processing logic...
}

// PayPalPayment implementation
type PayPalPayment struct{}

func (pp *PayPalPayment) ProcessPayment(amount float64) {
    fmt.Printf("Processing PayPal payment of $%.2f\n", amount)
    // Payment processing logic...
}

// Factory function
func paymentFactory(paymentType string) (Payment, error) {
    switch paymentType {
    case "CREDIT_CARD":
        return &CreditCardPayment{}, nil
    case "PAYPAL":
        return &PayPalPayment{}, nil
    default:
        return nil, fmt.Errorf("Unknown payment type: %s", paymentType)
    }
}

func paymentHandler(w http.ResponseWriter, r *http.Request) {
    var req map[string]interface{}
    json.NewDecoder(r.Body).Decode(&req)
    paymentType := req["type"].(string)
    amount := req["amount"].(float64)

    payment, err := paymentFactory(paymentType)
    if err != nil {
        http.Error(w, err.Error(), http.StatusBadRequest)
        return
    }
    payment.ProcessPayment(amount)

    w.WriteHeader(http.StatusOK)
    json.NewEncoder(w).Encode(map[string]string{"message": "Payment processed successfully."})
}

func main() {
    http.HandleFunc("/make_payment", paymentHandler)
    http.ListenAndServe(":8080", nil)
}
```

