from fastapi import FastAPI
import aio_pika
import asyncio

app = FastAPI()

async def get_rabbit_connection():
    return await aio_pika.connect_robust("amqp://user:password@localhost/")

@app.on_event("startup")
async def startup_event():
    app.state.rabbit_connection = await get_rabbit_connection()

@app.on_event("shutdown")
async def shutdown_event():
    await app.state.rabbit_connection.close()

@app.post("/notify")
async def notify(event_type: str, message: str):
    async with app.state.rabbit_connection:
        channel = await app.state.rabbit_connection.channel()
        await channel.default_exchange.publish(
            aio_pika.Message(body=message.encode()),
            routing_key=event_type,
        )
```

