    @Override
    public double calculatePrice(Order order) {
        // Implement dynamic pricing logic based on inventory, demand, etc.
        return order.getBasePrice() * (1 + getDynamicRate());
    }

    private double getDynamicRate() {
        // Example dynamic calculation
        return 0.05; // 5% increase
    }
}

