@RestController
@RequestMapping("/pricing")
public class PricingController {
    private final PricingContext pricingContext;

    public PricingController(PricingContext pricingContext) {
        this.pricingContext = pricingContext;
    }

    @PostMapping("/calculate")
    public double calculatePrice(@RequestBody Order order, @RequestParam String strategy) {
        switch (strategy) {
            case "discount":
                pricingContext.setStrategy(new DiscountPricingStrategy());
                break;
            case "dynamic":
                pricingContext.setStrategy(new DynamicPricingStrategy());
                break;
            default:
                throw new IllegalArgumentException("Invalid strategy");
        }
        return pricingContext.executeStrategy(order);
    }
}
