package main

import (
	"encoding/json"
	"net/http"
)

type Order struct {
	BasePrice float64 `json:"base_price"`
}

type PricingStrategy interface {
	CalculatePrice(order Order) float64
}

type DiscountPricingStrategy struct{}

func (d DiscountPricingStrategy) CalculatePrice(order Order) float64 {
	return order.BasePrice * 0.9 // 10% discount
}

type DynamicPricingStrategy struct{}

func (d DynamicPricingStrategy) CalculatePrice(order Order) float64 {
	return order.BasePrice * (1 + d.getDynamicRate())
}

func (d DynamicPricingStrategy) getDynamicRate() float64 {
	return 0.05 // 5% increase
}

type PricingContext struct {
	strategy PricingStrategy
}

func (p *PricingContext) executeStrategy(order Order) float64 {
	return p.strategy.CalculatePrice(order)
}

func pricingHandler(w http.ResponseWriter, r *http.Request) {
	var order Order
	var strategy string

	if err := json.NewDecoder(r.Body).Decode(&order); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	strategy = r.URL.Query().Get("strategy")

	var pricingStrategy PricingStrategy
	switch strategy {
	case "discount":
		pricingStrategy = DiscountPricingStrategy{}
	case "dynamic":
		pricingStrategy = DynamicPricingStrategy{}
	default:
		http.Error(w, "Invalid strategy", http.StatusBadRequest)
		return
	}

	pricingContext := PricingContext{strategy: pricingStrategy}
	price := pricingContext.executeStrategy(order)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(price)
}

func main() {
	http.HandleFunc("/pricing/calculate", pricingHandler)
	http.ListenAndServe(":8080", nil)
}
