# command.py
from abc import ABC, abstractmethod

class Command(ABC):
    @abstractmethod
    def execute(self):
        pass

    @abstractmethod
    def undo(self):
        pass

class Document:
    def __init__(self):
        self.content = ""

    def insert_text(self, text: str, position: int):
        self.content = self.content[:position] + text + self.content[position:]

    def remove_text(self, position: int, length: int):
        self.content = self.content[:position] + self.content[position + length:]

class InsertTextCommand(Command):
    def __init__(self, document: Document, text: str, position: int):
        self.document = document
        self.text = text
        self.position = position

    def execute(self):
        self.document.insert_text(self.text, self.position)

    def undo(self):
        self.document.remove_text(self.position, len(self.text))

class CommandManager:
    def __init__(self):
        self.command_stack = []
        self.undo_stack = []

    def execute_command(self, command: Command):
        command.execute()
        self.command_stack.append(command)
        self.undo_stack.clear()  # Clear redo stack

    def undo(self):
        if self.command_stack:
            command = self.command_stack.pop()
            command.undo()
            self.undo_stack.append(command)

    def redo(self):
        if self.undo_stack:
            command = self.undo_stack.pop()
            command.execute()
            self.command_stack.append(command)
