    c.document.RemoveText(c.position, len(c.text))
}

type CommandManager struct {
    commandStack []Command
    undoStack    []Command
}

func (cm *CommandManager) ExecuteCommand(command Command) {
    command.Execute()
    cm.commandStack = append(cm.commandStack, command)
    cm.undoStack = nil // Clear redo stack
}

func (cm *CommandManager) Undo() {
    if len(cm.commandStack) > 0 {
        command := cm.commandStack[len(cm.commandStack)-1]
        command.Undo()
        cm.commandStack = cm.commandStack[:len(cm.commandStack)-1]
        cm.undoStack = append(cm.undoStack, command)
    }
}

func (cm *CommandManager) Redo() {
    if len(cm.undoStack) > 0 {
        command := cm.undoStack[len(cm.undoStack)-1]
        command.Execute()
        cm.commandStack = append(cm.commandStack, command)
        cm.undoStack = cm.undoStack[:len(cm.undoStack)-1]
    }
}
