    db    *sqlx.DB
    rdb   *redis.Client
)

func init() {
    // Initialize SQL and Redis connections
    db = sqlx.MustConnect("sqlite3", "file:test.db")
    rdb = redis.NewClient(&redis.Options{
        Addr: "localhost:6379",
    })
}

func getProduct(w http.ResponseWriter, r *http.Request) {
    productId := r.URL.Query().Get("id")
    cachedProduct, err := rdb.Get("product:" + productId).Result()

    if err == nil {
        w.Write([]byte(cachedProduct))
        return
    }

    var product Product
    err = db.Get(&product, "SELECT * FROM products WHERE id = ?", productId)
    if err != nil {
        http.Error(w, "Product not found", http.StatusNotFound)
        return
    }

    rdb.Set("product:"+productId, product, 0)
    json.NewEncoder(w).Encode(product)
}

func main() {
    http.HandleFunc("/products", getProduct)
    log.Fatal(http.ListenAndServe(":8080", nil))
}
```

