    entitiesToSave  []interface{}
}

func NewUnitOfWork(db *sql.DB) *UnitOfWork {
    return &UnitOfWork{db: db}
}

func (uow *UnitOfWork) RegisterNew(entity interface{}) {
    uow.entitiesToSave = append(uow.entitiesToSave, entity)
}

// Commit saves all registered entities
func (uow *UnitOfWork) Commit() error {
    tx, err := uow.db.Begin()
    if err != nil {
        return err
    }
    for _, entity := range uow.entitiesToSave {
        // Assume entity has a save method
        if err := saveEntity(tx, entity); err != nil {
            tx.Rollback()
            return err
        }
    }
    if err := tx.Commit(); err != nil {
        return err
    }
    uow.entitiesToSave = []interface{}{}
    return nil
}

