app.post('/cart/:userId/items', async (req, res) => {
    const { userId } = req.params;
    const { productId, quantity } = req.body;

    const params = {
        TableName: 'ShoppingCart',
        Item: {
            userId,
            cartId: uuidv4(),
            productId,
            quantity,
        }
    };

    try {
        await dynamoDB.put(params).promise();
        res.status(200).send({ message: 'Item added to cart.' });
    } catch (error) {
        console.error(error);
        res.status(500).send({ error: 'Could not add item to the cart.' });
    }
});

