        Product product = new Product.ProductBuilder("Laptop", 1200)
                .description("High performance laptop")
                .attributes(List.of("16GB RAM", "512GB SSD"))
                .ratings(List.of(4.5, 4.0, 5.0))
                .build();

        System.out.println("Product created: " + product);
    }
}
