        self.name = name
        self.price = price
        self.description = description
        self.attributes = attributes or []
        self.ratings = ratings or []

    def __repr__(self):
        return f"Product(name={self.name}, price={self.price}, description={self.description}, attributes={self.attributes}, ratings={self.ratings})"

class ProductBuilder:
