package main

import (
    "fmt"
)

// Event interface
type Event interface{}

// Event types
type OrderPlaced struct {
    OrderID string
}

type InventoryUpdated struct {
    ProductID    string
    NewStockLevel int
}

type UserRegistered struct {
    UserID string
}

// Observer interface
type Observer interface {
    Update(Event)
}

// EventManager to manage observers
type EventManager struct {
    observers []Observer
}

func (em *EventManager) Subscribe(observer Observer) {
    em.observers = append(em.observers, observer)
}

func (em *EventManager) Notify(event Event) {
    for _, observer := range em.observers {
        observer.Update(event)
    }
}

// Concrete Observers
type InventoryService struct{}

func (is *InventoryService) Update(event Event) {
    switch e := event.(type) {
    case OrderPlaced:
        fmt.Printf("Inventory Service: Order placed with ID %s\n", e.OrderID)
    case InventoryUpdated:
        fmt.Printf("Inventory Service: Product %s stock updated to %d\n", e.ProductID, e.NewStockLevel)
