### Command Pattern with Undo/Redo Functionality

The Command Pattern is a behavioral design pattern that encapsulates a request as an object, thereby allowing parameterization of clients with queues, requests, and operations. This design is particularly useful in applications like text editors, where users frequently need to undo and redo changes.

Here, we will implement a command pattern with undo/redo capabilities for a text editor in Java, Python, and Go. Additionally, we will discuss performance considerations, common pitfalls, and testing strategies.

---

### 1. Complete Working Code

#### Java Implementation

```java
import java.util.Stack;

// Command Interface
interface Command {
    void execute();
    void unexecute();
}

// Concrete Command for Inserting Text
class InsertTextCommand implements Command {
    private StringBuilder textDocument;
    private String text;

    public InsertTextCommand(StringBuilder textDocument, String text) {
        this.textDocument = textDocument;
        this.text = text;
    }

    @Override
    public void execute() {
        textDocument.append(text);
    }

    @Override
    public void unexecute() {
        textDocument.delete(textDocument.length() - text.length(), textDocument.length());
    }
}

// Concrete Command for Deleting Text
class DeleteTextCommand implements Command {
    private StringBuilder textDocument;
    private String deletedText;

    public DeleteTextCommand(StringBuilder textDocument, String deletedText) {
        this.textDocument = textDocument;
        this.deletedText = deletedText;
    }

    @Override
    public void execute() {
        textDocument.delete(textDocument.length() - deletedText.length(), textDocument.length());
    }

    @Override
    public void unexecute() {
        textDocument.append(deletedText);
    }
}

// Invoker Class
class TextEditor {
    private Stack<Command> undoStack = new Stack<>();
    private Stack<Command> redoStack = new Stack<>();
    private StringBuilder textDocument = new StringBuilder();

    public void executeCommand(Command command) {
        command.execute();
        undoStack.push(command);
        redoStack.clear(); // Clear redo stack on new command
    }

    public void undo() {
        if (!undoStack.isEmpty()) {
            Command command = undoStack.pop();
            command.unexecute();
            redoStack.push(command);
        }
    }

    public void redo() {
        if (!redoStack.isEmpty()) {
            Command command = redoStack.pop();
            command.execute();
            undoStack.push(command);
        }
    }

    public String getText() {
        return textDocument.toString();
    }
}

// Example Usage
public class Main {
    public static void main(String[] args) {
        TextEditor editor = new TextEditor();
        editor.executeCommand(new InsertTextCommand(editor.textDocument, "Hello "));
        editor.executeCommand(new InsertTextCommand(editor.textDocument, "World!"));
        System.out.println(editor.getText()); // Hello World!

        editor.undo();
        System.out.println(editor.getText()); // Hello

        editor.redo();
        System.out.println(editor.getText()); // Hello World!
    }
}
```

