#### Go Implementation

```go
package main

import (
	"fmt"
)

// Command interface
type Command interface {
	Execute()
	Unexecute()
}

// InsertTextCommand struct
type InsertTextCommand struct {
	TextDocument *[]rune
	Text         string
}

func (cmd *InsertTextCommand) Execute() {
	*cmd.TextDocument = append(*cmd.TextDocument, []rune(cmd.Text)...)
}

func (cmd *InsertTextCommand) Unexecute() {
	*cmd.TextDocument = (*cmd.TextDocument)[:len(*cmd.TextDocument)-len(cmd.Text)]
}

// DeleteTextCommand struct
type DeleteTextCommand struct {
	TextDocument *[]rune
	Text         string
}

func (cmd *DeleteTextCommand) Execute() {
	*cmd.TextDocument = (*cmd.TextDocument)[:len(*cmd.TextDocument)-len(cmd.Text)]
}

func (cmd *DeleteTextCommand) Unexecute() {
	*cmd.TextDocument = append(*cmd.TextDocument, []rune(cmd.Text)...)
}

// TextEditor struct
type TextEditor struct {
	undoStack []Command
	redoStack []Command
	TextDocument []rune
}

func (editor *TextEditor) ExecuteCommand(command Command) {
	command.Execute()
	editor.undoStack = append(editor.undoStack, command)
	editor.redoStack = []Command{} // Clear redo stack
}

func (editor *TextEditor) Undo() {
	if len(editor.undoStack) > 0 {
		command := editor.undoStack[len(editor.undoStack)-1]
		editor.undoStack = editor.undoStack[:len(editor.undoStack)-1]
		command.Unexecute()
		editor.redoStack = append(editor.redoStack, command)
	}
}

func (editor *TextEditor) Redo() {
	if len(editor.redoStack) > 0 {
		command := editor.redoStack[len(editor.redoStack)-1]
		editor.redoStack = editor.redoStack[:len(editor.redoStack)-1]
		command.Execute()
		editor.undoStack = append(editor.undoStack, command)
	}
}

func (editor *TextEditor) GetText() string {
	return string(editor.TextDocument)
}

// Example Usage
func main() {
	editor := &TextEditor{}
	editor.ExecuteCommand(&InsertTextCommand{&editor.TextDocument, "Hello "})
	editor.ExecuteCommand(&InsertTextCommand{&editor.TextDocument, "World!"})
	fmt.Println(editor.GetText()) // Hello World!

	editor.Undo()
	fmt.Println(editor.GetText()) // Hello 

	editor.Redo()
	fmt.Println(editor.GetText()) // Hello World!
}
```

