import org.springframework.stereotype.Service;

@Service
public class PaymentService {

    @HystrixCommand(fallbackMethod = "fallbackProcessPayment", 
                    commandProperties = {
                        @HystrixProperty(name = "execution.isolation.thread.timeoutInMilliseconds", value = "200"),
                        @HystrixProperty(name = "circuitBreaker.requestVolumeThreshold", value = "10"),
                        @HystrixProperty(name = "circuitBreaker.sleepWindowInMilliseconds", value = "5000"),
                        @HystrixProperty(name = "circuitBreaker.errorThresholdPercentage", value = "20")
                    })
    public String processPayment(PaymentRequest request) {
        // Call to an external payment gateway
        return callPaymentGateway(request);
    }

    public String fallbackProcessPayment(PaymentRequest request) {
        return "Payment processing is currently unavailable. Please try again later.";
    }

    private String callPaymentGateway(PaymentRequest request) {
        // Simulated external call
        // In real case, you would call the payment gateway API here
    }
}
```

