import io.github.resilience4j.bulkhead.Bulkhead;
import io.github.resilience4j.bulkhead.BulkheadConfig;
import io.github.resilience4j.bulkhead.BulkheadRegistry;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.concurrent.CompletableFuture;

@Service
public class TransactionService {
    private final Bulkhead bulkhead;

    @Autowired
    public TransactionService(BulkheadRegistry bulkheadRegistry) {
        BulkheadConfig config = BulkheadConfig.custom()
                .maxConcurrentCalls(50) // Limit concurrent transactions
                .maxWaitDuration(Duration.ofMillis(500)) // Wait for 500ms if the limit is reached
                .build();
        this.bulkhead = bulkheadRegistry.bulkhead("transactionServiceBulkhead", config);
    }

    public CompletableFuture<String> processTransaction(Transaction transaction) {
        return CompletableFuture.supplyAsync(Bulkhead.decorateSupplier(bulkhead, () -> {
            // business logic for processing transactions
            return "Transaction Processed";
        }));
    }
}
```

