package main

import (
    "net/http"
    "github.com/gin-gonic/gin"
    "encoding/json"
    "io/ioutil"
)

const legacyAPIURL = "http://legacy-erp/api/inventory"

type LegacyInventoryResponse struct {
    ID       string `json:"id"`
    Quantity int    `json:"quantity"`
}

type InventoryResponse struct {
    ID       string `json:"id"`
    Quantity int    `json:"quantity"`
}

func main() {
    r := gin.Default()

    r.GET("/api/acl/inventory/:item_id", getInventory)

    r.Run()
}

func getInventory(c *gin.Context) {
