    resp, err := http.Get(legacyAPIURL + "/" + itemId)
    if err != nil {
        c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to call legacy API"})
        return
    }
    defer resp.Body.Close()

    body, _ := ioutil.ReadAll(resp.Body)
    var legacyResponse LegacyInventoryResponse
    json.Unmarshal(body, &legacyResponse)

    inventoryResponse := transformToNewModel(legacyResponse)
    c.JSON(http.StatusOK, inventoryResponse)
}

