#### Go Implementation

```go
package main

import (
	"sync/atomic"
	"unsafe"
)

type Node struct {
	value *TradeRequest
	next  *Node
}

type LockFreeQueue struct {
	head *Node
	tail *Node
}

func NewLockFreeQueue() *LockFreeQueue {
	dummy := &Node{}
	return &LockFreeQueue{head: dummy, tail: dummy}
}

func (q *LockFreeQueue) Enqueue(value *TradeRequest) {
	newNode := &Node{value: value}
	for {
		tail := atomic.LoadPointer((*unsafe.Pointer)(unsafe.Pointer(&q.tail)))
		next := (*Node)(tail).next

		if next != nil {
			atomic.CompareAndSwapPointer((*unsafe.Pointer)(unsafe.Pointer(&q.tail)), tail, unsafe.Pointer(next))
			continue
		}

		if atomic.CompareAndSwapPointer(&(*Node)(tail).next, nil, unsafe.Pointer(newNode)) {
			atomic.CompareAndSwapPointer((*unsafe.Pointer)(unsafe.Pointer(&q.tail)), tail, unsafe.Pointer(newNode))
			return
		}
	}
}

func (q *LockFreeQueue) Dequeue() *TradeRequest {
	for {
		head := atomic.LoadPointer((*unsafe.Pointer)(unsafe.Pointer(&q.head)))
		tail := atomic.LoadPointer((*unsafe.Pointer)(unsafe.Pointer(&q.tail)))
		next := (*Node)(head).next

		if head == tail {
			if next == nil {
				return nil // Queue is empty
			}
			atomic.CompareAndSwapPointer((*unsafe.Pointer)(unsafe.Pointer(&q.tail)), tail, unsafe.Pointer(next))
		} else {
			if atomic.CompareAndSwapPointer((*unsafe.Pointer)(unsafe.Pointer(&q.head)), head, unsafe.Pointer(next)) {
				return next.value
			}
		}
	}
}
