func updateInventory(db *sql.DB, id, version int, updatedItem InventoryItem) (InventoryItem, error) {
    var item InventoryItem
    err := db.QueryRow("UPDATE inventory_items SET quantity = $1, version = version + 1 WHERE id = $2 AND version = $3 RETURNING id, name, quantity, version",
        updatedItem.Quantity, id, version).Scan(&item.ID, &item.Name, &item.Quantity, &item.Version)

    if err != nil {
        return InventoryItem{}, fmt.Errorf("item not found or version mismatch: %v", err)
    }

    return item, nil
}

