    err := db.QueryRow("SELECT id, name, quantity, version FROM inventory_items WHERE id = $1", id).Scan(&item.ID, &item.Name, &item.Quantity, &item.Version)
    if err != nil {
        return InventoryItem{}, fmt.Errorf("item not found: %v", err)
    }
    return item, nil
}

