from threading import Lock

class Entity:
    def __init__(self, id):
        self.id = id

class IdentityMap:
    def __init__(self):
        self.map = {}
        self.lock = Lock()

    def get(self, id):
        return self.map.get(id)

    def put(self, entity):
        with self.lock:
            self.map[entity.id] = entity

    def evict(self, id):
        with self.lock:
            if id in self.map:
                del self.map[id]

class DataMapper:
    def find_by_id(self, id):
        # Simulate database access
        return Entity(id)

class Repository:
    def __init__(self):
        self.identity_map = IdentityMap()
        self.data_mapper = DataMapper()

    def find(self, id):
        entity = self.identity_map.get(id)
        if entity is None:
            entity = self.data_mapper.find_by_id(id)
            self.identity_map.put(entity)
        return entity
