type Entity struct {
	ID int
}

type IdentityMap struct {
	mapLock sync.RWMutex
	mapData map[int]*Entity
}

func NewIdentityMap() *IdentityMap {
	return &IdentityMap{mapData: make(map[int]*Entity)}
}

func (im *IdentityMap) Get(id int) *Entity {
	im.mapLock.RLock()
	defer im.mapLock.RUnlock()
	return im.mapData[id]
}

func (im *IdentityMap) Put(entity *Entity) {
	im.mapLock.Lock()
	defer im.mapLock.Unlock()
	im.mapData[entity.ID] = entity
}

func (im *IdentityMap) Evict(id int) {
	im.mapLock.Lock()
	defer im.mapLock.Unlock()
	delete(im.mapData, id)
}

type DataMapper struct{}

func (dm *DataMapper) FindById(id int) *Entity {
