type Employee struct {
    ID      int
    Name    string
    Email   string
    Position string
    Version int
}

type EmployeeRepository struct {
    db *sql.DB
}

func (repo *EmployeeRepository) UpdateEmployee(empID int, name, email, position string, version int) (bool, error) {
    query := `UPDATE employees SET name = ?, email = ?, position = ?, version = version + 1 WHERE id = ? AND version = ?`
    res, err := repo.db.Exec(query, name, email, position, empID, version)
    if err != nil {
        return false, err
    }
    rowsAffected, err := res.RowsAffected()
    return rowsAffected > 0, err
}

func (repo *EmployeeRepository) GetEmployee(empID int) (*Employee, error) {
    query := `SELECT * FROM employees WHERE id = ?`
    row := repo.db.QueryRow(query, empID)
    emp := &Employee{}
    err := row.Scan(&emp.ID, &emp.Name, &emp.Email, &emp.Position, &emp.Version)
    if err == sql.ErrNoRows {
        return nil, nil
    }
    return emp, err
}
