### 2.3 Go Implementation

```go
package main

import (
    "database/sql"
    _ "github.com/mattn/go-sqlite3"
)

type User struct {
    ID       int
    Username string
    Email    string
}

type UserGateway struct {
    db *sql.DB
}

func NewUserGateway(db *sql.DB) *UserGateway {
    return &UserGateway{db: db}
}

func (ug *UserGateway) Insert(user User) error {
    _, err := ug.db.Exec("INSERT INTO users (username, email) VALUES (?, ?)", user.Username, user.Email)
    return err
}

func (ug *UserGateway) FindByID(id int) (*User, error) {
    row := ug.db.QueryRow("SELECT id, username, email FROM users WHERE id = ?", id)
    user := &User{}
    if err := row.Scan(&user.ID, &user.Username, &user.Email); err != nil {
        return nil, err
    }
    return user, nil
}

func (ug *UserGateway) FindAll(offset, limit int) ([]User, error) {
    rows, err := ug.db.Query("SELECT id, username, email FROM users LIMIT ? OFFSET ?", limit, offset)
    if err != nil {
        return nil, err
    }
    defer rows.Close()

    var users []User
    for rows.Next() {
        user := User{}
        if err := rows.Scan(&user.ID, &user.Username, &user.Email); err != nil {
            return nil, err
        }
        users = append(users, user)
    }
    return users, nil
}

func (ug *UserGateway) Update(user User) error {
    _, err := ug.db.Exec("UPDATE users SET username = ?, email = ? WHERE id = ?", user.Username, user.Email, user.ID)
    return err
}

func (ug *UserGateway) Delete(id int) error {
    _, err := ug.db.Exec("DELETE FROM users WHERE id = ?", id)
    return err
}
```

