// Go: resource_service.go
package main

import "sync"

type ResourceService struct {
    resources map[string]Resource
    mu        sync.Mutex
}

func NewResourceService() *ResourceService {
    return &ResourceService{resources: make(map[string]Resource)}
}

func (s *ResourceService) GetResource(id string) Resource {
    s.mu.Lock()
    defer s.mu.Unlock()
    return s.resources[id]
}

func (s *ResourceService) UpdateResource(newResource Resource) bool {
    s.mu.Lock()
    defer s.mu.Unlock()

    currentResource, exists := s.resources[newResource.ID]
    if exists && currentResource.Version == newResource.Version {
        s.resources[newResource.ID] = newResource
        return true
    }
    return false
}
