import java.util.Queue;

public class ChangeQueue {
    private Queue<Resource> queue = new LinkedList<>();

    public void enqueue(Resource resource) {
        queue.add(resource);
    }

    public Resource dequeue() {
        return queue.poll();
    }

    public boolean isEmpty() {
        return queue.isEmpty();
    }
}
