func (s *BankAccountService) ReadAccount(accountID int) (*BankAccount, error) {
    var account BankAccount
    query := "SELECT id, account_holder, balance, version FROM bank_accounts WHERE id = $1"
    err := s.db.QueryRow(query, accountID).Scan(&account.ID, &account.AccountHolder, &account.Balance, &account.Version)
    if err != nil {
        return nil, err
    }
    return &account, nil
}

func (s *BankAccountService) UpdateAccount(account *BankAccount) (bool, error) {
    query := "UPDATE bank_accounts SET balance = $1, version = version + 1 WHERE id = $2 AND version = $3"
    res, err := s.db.Exec(query, account.Balance, account.ID, account.Version)
    if err != nil {
        return false, err
    }
    rowsAffected, _ := res.RowsAffected()
    return rowsAffected > 0, nil
}
