import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class RestaurantGateway {
    private Connection connection;

    public RestaurantGateway(Connection connection) {
        this.connection = connection;
    }

    public void addRestaurant(String name, String location, String cuisineType) throws SQLException {
        String sql = "INSERT INTO Restaurants (name, location, cuisine_type) VALUES (?, ?, ?)";
        try (PreparedStatement stmt = connection.prepareStatement(sql)) {
            stmt.setString(1, name);
            stmt.setString(2, location);
            stmt.setString(3, cuisineType);
            stmt.executeUpdate();
        }
    }

    public List<Restaurant> getAllRestaurants() throws SQLException {
        List<Restaurant> restaurants = new ArrayList<>();
        String sql = "SELECT * FROM Restaurants";
        try (Statement stmt = connection.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {
            while (rs.next()) {
                restaurants.add(new Restaurant(rs.getInt("id"), rs.getString("name"),
                        rs.getString("location"), rs.getString("cuisine_type")));
            }
        }
        return restaurants;
    }
}
```

