	Name  string
	Price float64
}

type ShoppingCart struct {
	Products []Product
}

func (sc *ShoppingCart) AddProduct(product Product) {
	sc.Products = append(sc.Products, product)
}

func (sc *ShoppingCart) RemoveProduct(product Product) {
	for i, p := range sc.Products {
		if p.ID == product.ID {
			sc.Products = append(sc.Products[:i], sc.Products[i+1:]...)
			break
		}
	}
}

func (sc *ShoppingCart) CalculateTotal() float64 {
	total := 0.0
	for _, p := range sc.Products {
		total += p.Price
	}
	return total
}

