type OrderEventHandler struct {
    consumer *kafka.Consumer
}

func NewOrderEventHandler(broker string) *OrderEventHandler {
    c, _ := kafka.NewConsumer(&kafka.ConfigMap{
        "bootstrap.servers": broker,
        "group.id":          "order-event-handlers",
        "auto.offset.reset": "earliest",
    })
    c.SubscribeTopics([]string{"order-placed", "order-shipped", "order-cancelled"}, nil)
    return &OrderEventHandler{consumer: c}
}

func (eh *OrderEventHandler) HandleEvents() {
    for {
        msg, err := eh.consumer.ReadMessage(-1)
        if err == nil {
            switch *msg.TopicPartition.Topic {
            case "order-placed":
                var event OrderPlaced
                json.Unmarshal(msg.Value, &event)
                log.Printf("Order placed: %s", event.OrderID)
            // Handle other events similarly
            }
        }
    }
}
