        BusinessLogicStrategy strategy = getStrategy(tenantId);
        strategy.execute();
    }

    private BusinessLogicStrategy getStrategy(String tenantId) {
        if ("TenantA".equals(tenantId)) {
            return new TenantAStrategy();
        } else {
            return new TenantBStrategy();
        }
    }
}
