    PreferredCategories []string
}

func (s CategorySpecification) IsSatisfiedBy(item Product) bool {
    for _, category := range s.PreferredCategories {
        if item.Category == category {
            return true
        }
    }
    return false
}

// category_specification.ts (TypeScript)
class CategorySpecification implements Specification<Product> {
