    def __init__(self, is_premium_user):
        self.is_premium_user = is_premium_user

    def is_satisfied_by(self, item) -> bool:
        if self.is_premium_user:
            return 'premium' in item.promotions
        return True

// premium_user_specification.go (Go)
type PremiumUserSpecification struct {
    IsPremiumUser bool
}

func (s PremiumUserSpecification) IsSatisfiedBy(item Product) bool {
    if s.IsPremiumUser {
        return item.HasPremiumPromotion()
    }
    return true
}

// premium_user_specification.ts (TypeScript)
