        this.isPremiumUser = isPremiumUser;
    }

    isSatisfiedBy(product: Product): boolean {
        if (this.isPremiumUser) {
            return product.promotions.includes('premium');
        }
        return true;
    }
}
```

### Step 3: Combine Specifications

We will create a composite specification that combines multiple specifications using logical operators (AND, OR).

```java
// AndSpecification.java (Java)
public class AndSpecification<T> implements Specification<T> {
    private final Specification<T> spec1;
    private final Specification<T> spec2;

    public AndSpecification(Specification<T> spec1, Specification<T> spec2) {
        this.spec1 = spec1;
        this.spec2 = spec2;
    }

    @Override
    public boolean isSatisfiedBy(T item) {
        return spec1.isSatisfiedBy(item) && spec2.isSatisfiedBy(item);
    }
}

// AndSpecification.py (Python)
class AndSpecification(Specification):
    def __init__(self, spec1, spec2):
        self.spec1 = spec1
        self.spec2 = spec2

    def is_satisfied_by(self, item) -> bool:
        return self.spec1.is_satisfied_by(item) and self.spec2.is_satisfied_by(item)

# AndSpecification.go (Go)
type AndSpecification[T any] struct {
    Spec1 Specification[T]
    Spec2 Specification[T]
}

func (s AndSpecification[T]) IsSatisfiedBy(item T) bool {
    return s.Spec1.IsSatisfiedBy(item) && s.Spec2.IsSatisfiedBy(item)
}

// AndSpecification.ts (TypeScript)
class AndSpecification<T> implements Specification<T> {
    constructor(private spec1: Specification<T>, private spec2: Specification<T>) {}

    isSatisfiedBy(item: T): boolean {
        return this.spec1.isSatisfiedBy(item) && this.spec2.isSatisfiedBy(item);
    }
}
```

