```java
// ProductService.java (Java)
public class ProductService {
    private final List<Product> products;

    public ProductService(List<Product> products) {
        this.products = products;
    }

    public List<Product> filterProducts(User user) {
        Specification<Product> spec = new AvailabilitySpecification()
                .and(new PriceSpecification(user.getMaxPrice()))
                .and(new CategorySpecification(user.getPreferredCategories()))
                .and(new PremiumUserSpecification(user.isPremiumUser()));

        return products.stream()
                .filter(spec::isSatisfiedBy)
                .collect(Collectors.toList());
    }
}

// product_service.py (Python)
