                PriceSpecification(user.max_price),
                AndSpecification(
                    CategorySpecification(user.preferred_categories),
                    PremiumUserSpecification(user.is_premium_user)
                )
            )
        )

        return [product for product in self.products if spec.is_satisfied_by(product)]

