// ShoppingCart.java
import java.util.HashMap;
import java.util.Map;

public class ShoppingCart {
    private Map<Product, Integer> items = new HashMap<>();
    private long lastUpdated;

    public void addItem(Product product, int quantity) {
        items.put(product, items.getOrDefault(product, 0) + quantity);
        lastUpdated = System.currentTimeMillis();
    }

    public void removeItem(Product product) {
        items.remove(product);
        lastUpdated = System.currentTimeMillis();
    }

    public Order checkout() {
        Order order = new Order();
        items.forEach((product, quantity) -> order.addItem(product, quantity));
        items.clear(); // Clear cart after checkout
        return order;
    }

    public boolean isAbandoned(long timeoutMillis) {
        return (System.currentTimeMillis() - lastUpdated) > timeoutMillis;
    }
}
```

