	Product Product
	Quantity int
}

func (item OrderItem) TotalPrice() float64 {
	return item.Product.Price * float64(item.Quantity)
}

type Order struct {
	Items       []OrderItem
	TotalAmount float64
	Finalized   bool
}

func (o *Order) AddItem(product Product, quantity int) {
	if o.Finalized {
		panic("Cannot modify a finalized order.")
	}
	if quantity <= 0 {
		panic("Quantity must be greater than zero.")
	}
	o.Items = append(o.Items, OrderItem{Product: product, Quantity: quantity})
	o.calculateTotal()
}

func (o *Order) FinalizeOrder() {
	o.Finalized = true
}

func (o *Order) calculateTotal() {
	o.TotalAmount = 0.0
	for _, item := range o.Items {
		o.TotalAmount += item.TotalPrice()
	}
}

// shopping_cart.go
type ShoppingCart struct {
	Items       map[Product]int
	LastUpdated int64
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{Items: make(map[Product]int)}
}

func (cart *ShoppingCart) AddItem(product Product, quantity int) {
	cart.Items[product] += quantity
	cart.LastUpdated = currentTime()
}

func (cart *ShoppingCart) RemoveItem(product Product) {
	delete(cart.Items, product)
	cart.LastUpdated = currentTime()
}

func (cart *ShoppingCart) Checkout() Order {
	order := Order{}
	for product, quantity := range cart.Items {
		order.AddItem(product, quantity)
	}
	cart.Items = make(map[Product]int) // Clear cart after checkout
	return order
}

func (cart *ShoppingCart) IsAbandoned(timeout int64) bool {
	return (currentTime() - cart.LastUpdated) > timeout
}

func currentTime() int64 {
	return time.Now().UnixNano() / int64(time.Millisecond)
}
