// ShoppingCart.ts
export class ShoppingCart {
    private items: Map<Product, number> = new Map();
    private lastUpdated: number = Date.now();

    addItem(product: Product, quantity: number): void {
        this.items.set(product, (this.items.get(product) || 0) + quantity);
        this.lastUpdated = Date.now();
    }

    removeItem(product: Product): void {
        this.items.delete(product);
        this.lastUpdated = Date.now();
    }

    checkout(): Order {
        const order = new Order();
        this.items.forEach((quantity, product) => {
            order.addItem(product, quantity);
        });
        this.items.clear(); // Clear cart after checkout
        return order;
    }

    isAbandoned(timeout: number): boolean {
        return (Date.now() - this.lastUpdated) > timeout;
    }
}
