## 5. Real-Time Updates
To enable real-time updates, we can use WebSocket or Server-Sent Events. Hereâ€™s how to set up WebSocket for handling real-time notifications.

### 5.1 WebSocket Implementation (Node.js)
```javascript
const WebSocket = require('ws');

const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', (ws) => {
    console.log('Client connected');

    ws.on('message', (message) => {
        console.log('Received: %s', message);
    });

    // Notify clients of new customer addition
    app.post('/api/customers', async (req, res) => {
        try {
            const customer = await Customer.create(req.body);
            wss.clients.forEach(client => {
                if (client.readyState === WebSocket.OPEN) {
                    client.send(JSON.stringify(customer));
                }
            });
            res.status(201).json(customer);
        } catch (error) {
            res.status(400).json({ error: error.message });
        }
    });
});
```

### 5.2 Client-Side WebSocket Connection (Angular)
```typescript
// src/app/customer/customer.service.ts
import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class CustomerService {
  private customersSubject = new BehaviorSubject<Customer[]>([]);
  public customers$ = this.customersSubject.asObservable();

  private websocket: WebSocket;

  constructor() {
    this.connectWebSocket();
  }

  private connectWebSocket() {
    this.websocket = new WebSocket('ws://localhost:8080');

    this.websocket.onmessage = (event) => {
      const customer: Customer = JSON.parse(event.data);
      this.customersSubject.next([...this.customersSubject.value, customer]);
    };
  }

  // Other methods...
}
