package main

import (
    "sync"
)

type Investment struct {
    ID     string
    Type   string
    Amount float64
}

type PortfolioModel struct {
    investments map[string]Investment
    cache       map[string]Investment
    mu          sync.RWMutex
}

func NewPortfolioModel() *PortfolioModel {
    return &PortfolioModel{
        investments: make(map[string]Investment),
        cache:       make(map[string]Investment),
    }
}

func (pm *PortfolioModel) FetchInvestment(id string) (Investment, error) {
    pm.mu.RLock()
    investment, exists := pm.cache[id]
    pm.mu.RUnlock()

    if exists {
        return investment, nil
    }

    investment = pm.fetchFromDatabase(id)
    pm.mu.Lock()
    pm.cache[id] = investment
    pm.mu.Unlock()
    return investment, nil
}

func (pm *PortfolioModel) fetchFromDatabase(id string) Investment {
    // Simulate database access
    return Investment{ID: id, Type: "Stock", Amount: 100.0}
}

// Other business logic methods...
```

