```typescript
import { observable, action, computed } from "mobx";
import axios from "axios";

class FinancialInstrument {
    @observable id: number;
    @observable name: string;
    @observable value: number;

    constructor(id: number, name: string, value: number) {
        this.id = id;
        this.name = name;
        this.value = value;
    }
}

class FinancialInstrumentStore {
    @observable instruments: FinancialInstrument[] = [];

    @action async fetchInstruments() {
        const response = await axios.get('/api/instruments');
        this.instruments = response.data.map((data: any) => new FinancialInstrument(data.id, data.name, data.value));
    }

    @action async createInstrument(name: string, value: number) {
        const response = await axios.post('/api/instruments', { name, value });
        this.instruments.push(new FinancialInstrument(response.data.id, response.data.name, response.data.value));
    }
}

export const store = new FinancialInstrumentStore();
```

