        if (cart == null) {
            cart = new Cart();
        }
        cart.addItem(product);
        cartRepository.save(userId, cart);
    }

    public void removeItem(Long userId, Product product) {
        Cart cart = cartRepository.findByUserId(userId);
        if (cart != null) {
            cart.removeItem(product);
            cartRepository.save(userId, cart);
        }
    }
}
