import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.PostMapping;

@Controller
public class CartController {
    @Autowired
    private CartService cartService;

    @PostMapping("/cart/add")
    public String addToCart(Long userId, Long productId) {
        Product product = productService.getProductById(productId);
        cartService.addItem(userId, product);
        return "redirect:/cart"; // Redirect to cart view
    }

    @PostMapping("/cart/remove")
    public String removeFromCart(Long userId, Long productId) {
        Product product = productService.getProductById(productId);
        cartService.removeItem(userId, product);
        return "redirect:/cart"; // Redirect to cart view
    }
}
