func (v *UserProfileViewHelper) RenderUserProfile(c *gin.Context) {
    userId := c.Param("userId")
    profile := v.cacheManager.GetCachedUserProfile(userId)
    if profile == nil {
        profile = v.userService.FetchUserProfile(userId)
        v.cacheManager.CacheUserProfile(userId, profile)
    }
    c.HTML(http.StatusOK, "user_profile.html", gin.H{"profile": profile})
