type CacheManager struct {
    cache sync.Map
}

func (c *CacheManager) GetCachedUserProfile(userId string) *UserProfile {
    profile, _ := c.cache.Load(userId)
    return profile.(*UserProfile)
}

func (c *CacheManager) CacheUserProfile(userId string, profile *UserProfile) {
    c.cache.Store(userId, profile)
}

func main() {
