    userService := &UserService{}
    cacheManager := &CacheManager{}
    viewHelper := UserProfileViewHelper{userService, cacheManager}

    r.GET("/userProfile/:userId", viewHelper.RenderUserProfile)
    r.Run(":8080")
}
